            targetValue === null ||
            startValue === null ||
            endValue === null ||
            !Number.isFinite(targetValue) ||
            !Number.isFinite(startValue) ||
            !Number.isFinite(endValue) ||
            !Number.isInteger(targetValue) ||
            !Number.isInteger(startValue) ||
            !Number.isInteger(endValue)
