            method === "ownKeys" &&
            call.arguments.length === 1 &&
            this.isUnshadowedGlobalIdentifier(recv, "Reflect") &&
            this.isSideEffectFreeObjectEnumerationOperand(call.arguments[0]!, seenConsts)
